-- Synthetic identities and Storage metadata; everything rolls back.
begin;
create function pg_temp.assert_true(value boolean,label text) returns void language plpgsql as $$
begin if value is not true then raise exception 'FAIL: %',label; end if; end $$;
create function pg_temp.must_fail(command text) returns void language plpgsql as $$
begin begin execute command; exception when others then return; end;
raise exception 'FAIL: unauthorized operation succeeded: %',command; end $$;
select set_config('trash.leader',gen_random_uuid()::text,true),set_config('trash.member',gen_random_uuid()::text,true),set_config('trash.supervisor',gen_random_uuid()::text,true),set_config('trash.outsider',gen_random_uuid()::text,true);
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data)
select current_setting('trash.'||n)::uuid,'rf-trash-'||current_setting('trash.'||n)||'@example.invalid',now(),jsonb_build_object('full_name','Trash test '||n) from unnest(array['leader','member','supervisor','outsider']) n;
set local role authenticated;
select set_config('request.jwt.claim.sub',current_setting('trash.leader'),true);
select set_config('trash.w',public.rf_create_workspace('Trash test','Disposable research','Test Leader')::text,true);
insert into public.rf_workspace_invitations(workspace_id,email,role) select current_setting('trash.w')::uuid,'rf-trash-'||current_setting('trash.'||n)||'@example.invalid',n from unnest(array['member','supervisor']) n;
select set_config('trash.member_token',(select token::text from public.rf_workspace_invitations where workspace_id=current_setting('trash.w')::uuid and role='member'),true),set_config('trash.supervisor_token',(select token::text from public.rf_workspace_invitations where workspace_id=current_setting('trash.w')::uuid and role='supervisor'),true);
select set_config('request.jwt.claim.sub',current_setting('trash.member'),true);
select public.rf_accept_invitation(current_setting('trash.member_token')::uuid,'Test Member');
select set_config('request.jwt.claim.sub',current_setting('trash.supervisor'),true);
select public.rf_accept_invitation(current_setting('trash.supervisor_token')::uuid,'Test Supervisor');
select set_config('request.jwt.claim.sub',current_setting('trash.leader'),true);
select set_config('trash.folder',(select id::text from public.rf_document_folders where workspace_id=current_setting('trash.w')::uuid limit 1),true);
select set_config('trash.doc',(public.rf_collaborate('document_create',jsonb_build_object('workspace_id',current_setting('trash.w'),'folder_id',current_setting('trash.folder'),'title','Recoverable document','restricted',false))->>'id'),true);
select set_config('trash.path',current_setting('trash.w')||'/'||current_setting('trash.leader')||'/'||gen_random_uuid()||'.txt',true);
reset role;
insert into storage.objects(bucket_id,name,metadata) values('researchflow-files',current_setting('trash.path'),'{"mimetype":"text/plain","size":12}');
set local role authenticated;
select set_config('trash.version',(public.rf_collaborate('file_register',jsonb_build_object('workspace_id',current_setting('trash.w'),'path',current_setting('trash.path'),'name','trash-test.txt','document_id',current_setting('trash.doc')))->>'id'),true);
select set_config('trash.submission',(public.rf_collaborate('review_request',jsonb_build_object('workspace_id',current_setting('trash.w'),'version_id',current_setting('trash.version')))->>'id'),true);
select set_config('request.jwt.claim.sub',current_setting('trash.member'),true);
select pg_temp.must_fail(format('select public.rf_collaborate(''document_trash'',%L::jsonb)',jsonb_build_object('workspace_id',current_setting('trash.w'),'id',current_setting('trash.doc'))));
select set_config('request.jwt.claim.sub',current_setting('trash.supervisor'),true);
select pg_temp.must_fail(format('select public.rf_collaborate(''document_trash'',%L::jsonb)',jsonb_build_object('workspace_id',current_setting('trash.w'),'id',current_setting('trash.doc'))));
select set_config('request.jwt.claim.sub',current_setting('trash.leader'),true);
select public.rf_collaborate('document_trash',jsonb_build_object('workspace_id',current_setting('trash.w'),'id',current_setting('trash.doc')));
select public.rf_collaborate('document_trash',jsonb_build_object('workspace_id',current_setting('trash.w'),'id',current_setting('trash.doc')));
select pg_temp.assert_true((select trashed_at is not null from public.rf_documents where id=current_setting('trash.doc')::uuid),'leader can read Trash');
select pg_temp.assert_true((select count(*)=1 from public.rf_document_versions where id=current_setting('trash.version')::uuid),'file version preserved');
select pg_temp.must_fail(format('select public.rf_collaborate(''document_comment'',%L::jsonb)',jsonb_build_object('workspace_id',current_setting('trash.w'),'document_id',current_setting('trash.doc'),'body','Not allowed in Trash')));
select set_config('request.jwt.claim.sub',current_setting('trash.member'),true);
select pg_temp.assert_true((select count(*)=0 from public.rf_documents where id=current_setting('trash.doc')::uuid),'member cannot read Trash');
select pg_temp.assert_true((select count(*)=0 from public.rf_files where document_id=current_setting('trash.doc')::uuid),'member cannot read trashed file metadata');
select pg_temp.assert_true((select count(*)=0 from storage.objects where name=current_setting('trash.path')),'member cannot sign trashed bytes');
select pg_temp.must_fail(format('select public.rf_collaborate(''document_restore'',%L::jsonb)',jsonb_build_object('workspace_id',current_setting('trash.w'),'id',current_setting('trash.doc'))));
select set_config('request.jwt.claim.sub',current_setting('trash.supervisor'),true);
select pg_temp.assert_true((select count(*)=0 from public.rf_submissions where id=current_setting('trash.submission')::uuid),'trashed review hidden from lecturer');
select pg_temp.must_fail(format('select public.rf_collaborate(''review_decide'',%L::jsonb)',jsonb_build_object('workspace_id',current_setting('trash.w'),'submission_id',current_setting('trash.submission'),'kind','Academic','decision','Approved','feedback','Denied while trashed')));
select set_config('request.jwt.claim.sub',current_setting('trash.outsider'),true);
select pg_temp.must_fail(format('select public.rf_collaborate(''document_restore'',%L::jsonb)',jsonb_build_object('workspace_id',current_setting('trash.w'),'id',current_setting('trash.doc'))));
select set_config('request.jwt.claim.sub',current_setting('trash.leader'),true);
select public.rf_collaborate('document_restore',jsonb_build_object('workspace_id',current_setting('trash.w'),'id',current_setting('trash.doc')));
select public.rf_collaborate('document_archive',jsonb_build_object('workspace_id',current_setting('trash.w'),'id',current_setting('trash.doc')));
select public.rf_collaborate('document_unarchive',jsonb_build_object('workspace_id',current_setting('trash.w'),'id',current_setting('trash.doc')));
select pg_temp.assert_true((select not archived and trashed_at is null from public.rf_documents where id=current_setting('trash.doc')::uuid),'restore and unarchive work independently');
select set_config('request.jwt.claim.sub',current_setting('trash.supervisor'),true);
select pg_temp.assert_true((select count(*)=1 from public.rf_submissions where id=current_setting('trash.submission')::uuid),'restored pending review returns');
select public.rf_collaborate('review_decide',jsonb_build_object('workspace_id',current_setting('trash.w'),'submission_id',current_setting('trash.submission'),'kind','Academic','decision','Approved','feedback','Lecturer feedback after restore'));
select pg_temp.assert_true((select status='Approved' from public.rf_submissions where id=current_setting('trash.submission')::uuid),'independent lecturer decision works after restore');
select set_config('request.jwt.claim.sub',current_setting('trash.leader'),true);
select pg_temp.must_fail(format('select public.rf_collaborate(''review_withdraw'',%L::jsonb)',jsonb_build_object('workspace_id',current_setting('trash.w'),'submission_id',current_setting('trash.submission'),'reason','Cannot change an academic decision')));
select set_config('trash.path2',current_setting('trash.w')||'/'||current_setting('trash.leader')||'/'||gen_random_uuid()||'.txt',true);
reset role;
insert into storage.objects(bucket_id,name,metadata) values('researchflow-files',current_setting('trash.path2'),'{"mimetype":"text/plain","size":24}');
set local role authenticated;
select set_config('trash.version2',(public.rf_collaborate('file_register',jsonb_build_object('workspace_id',current_setting('trash.w'),'path',current_setting('trash.path2'),'name','corrected-test.txt','document_id',current_setting('trash.doc')))->>'id'),true);
select set_config('trash.pending',(public.rf_collaborate('review_request',jsonb_build_object('workspace_id',current_setting('trash.w'),'version_id',current_setting('trash.version')))->>'id'),true);
select set_config('request.jwt.claim.sub',current_setting('trash.member'),true);
select pg_temp.must_fail(format('select public.rf_collaborate(''review_withdraw'',%L::jsonb)',jsonb_build_object('workspace_id',current_setting('trash.w'),'submission_id',current_setting('trash.pending'),'reason','Not the requester')));
select set_config('request.jwt.claim.sub',current_setting('trash.supervisor'),true);
select pg_temp.must_fail(format('select public.rf_collaborate(''review_correct'',%L::jsonb)',jsonb_build_object('workspace_id',current_setting('trash.w'),'submission_id',current_setting('trash.pending'),'version_id',current_setting('trash.version2'),'reason','Not the requester')));
select public.rf_collaborate('review_decide',jsonb_build_object('workspace_id',current_setting('trash.w'),'submission_id',current_setting('trash.pending'),'kind','Academic','decision','Revision Requested','feedback','Use a corrected draft'));
select set_config('request.jwt.claim.sub',current_setting('trash.leader'),true);
select set_config('trash.pending',(public.rf_collaborate('review_request',jsonb_build_object('workspace_id',current_setting('trash.w'),'version_id',current_setting('trash.version')))->>'id'),true);
select pg_temp.must_fail(format('select public.rf_collaborate(''review_correct'',%L::jsonb)',jsonb_build_object('workspace_id',current_setting('trash.w'),'submission_id',current_setting('trash.pending'),'version_id',gen_random_uuid(),'reason','Invalid replacement must roll back')));
select pg_temp.assert_true((select status='Submitted for Review' from public.rf_submissions where id=current_setting('trash.pending')::uuid),'failed replacement leaves original pending');
select set_config('trash.replacement',(public.rf_collaborate('review_correct',jsonb_build_object('workspace_id',current_setting('trash.w'),'submission_id',current_setting('trash.pending'),'version_id',current_setting('trash.version2'),'reason','Wrong version selected'))->>'id'),true);
select pg_temp.assert_true((select status='Withdrawn' and correction_reason='Wrong version selected' and version_id=current_setting('trash.version')::uuid from public.rf_submissions where id=current_setting('trash.pending')::uuid),'original evidence preserved with withdrawal reason');
select pg_temp.assert_true((select status='Submitted for Review' and replaces_submission_id=current_setting('trash.pending')::uuid and version_id=current_setting('trash.version2')::uuid from public.rf_submissions where id=current_setting('trash.replacement')::uuid),'replacement points to corrected version');
select set_config('request.jwt.claim.sub',current_setting('trash.supervisor'),true);
select pg_temp.must_fail(format('select public.rf_collaborate(''review_decide'',%L::jsonb)',jsonb_build_object('workspace_id',current_setting('trash.w'),'submission_id',current_setting('trash.pending'),'kind','Academic','decision','Approved','feedback','Stale withdrawn request must fail')));
select public.rf_collaborate('review_decide',jsonb_build_object('workspace_id',current_setting('trash.w'),'submission_id',current_setting('trash.replacement'),'kind','Academic','decision','Approved','feedback','Corrected version reviewed'));
select set_config('request.jwt.claim.sub',current_setting('trash.leader'),true);
select set_config('trash.phase',(select id::text from public.rf_research_phases where workspace_id=current_setting('trash.w')::uuid order by position limit 1),true);
select set_config('trash.phase_submission',(public.rf_collaborate('review_request',jsonb_build_object('workspace_id',current_setting('trash.w'),'phase_id',current_setting('trash.phase')))->>'id'),true);
select public.rf_collaborate('review_withdraw',jsonb_build_object('workspace_id',current_setting('trash.w'),'submission_id',current_setting('trash.phase_submission'),'reason','Milestone not ready'));
select pg_temp.assert_true((select review_state='Not requested' from public.rf_research_phases where id=current_setting('trash.phase')::uuid),'withdrawal restores prior milestone review state');
rollback;
select 'PASS: leader-only Trash, Storage isolation, restore/unarchive, pending correction/withdrawal, atomic rejection, immutable original evidence and independent lecturer review; all fixtures rolled back' as result;
